docker exec startuphafen-devcontainer-maildev-1 node -e '
const net=require("net");
const s=net.connect(1025,"127.0.0.1");
let buf="",expect="220",step=0;
const seq=["","EHLO validator","MAIL FROM:<test@startuphafen.de>","RCPT TO:<user@example.com>","DATA","From: noreply@startuphafen.de","To: user@example.com","Subject: validation-test","","This is a maildev validation email.","",".","QUIT"];
const exps=["220","250","250","250","354","354","354","354","354","354","354","354","354","250","221"];
s.on("data",d=>{
  buf+=d.toString();
  const m=buf.match(/^(\d{3})/m);
  if(m && m[1]===expect){
    if(step>0) console.log(">",seq[step-1].slice(0,40),"->",m[1]);
    buf="";
    step++;
    if(step>=seq.length){ s.end(); return; }
    expect=exps[step];
    s.write(seq[step]+"\r\n");
  }
});
s.on("end",()=>{ console.log("SMTP SESSION COMPLETE"); process.exit(0); });
setTimeout(()=>{ console.log("TIMEOUT step",step); process.exit(1); },8000);
'
